INSERT INTO _phase1_creation_guard SELECT 'all copied rows retain historical null provenance', NOT EXISTS
 (SELECT 1 FROM product_creation_jobs WHERE objective_source_product_conversation_id IS NOT NULL
 OR objective_source_transcript_id IS NOT NULL OR objective_source_message_id IS NOT NULL OR objective_source_tool_use_id IS NOT NULL);
INSERT INTO _phase1_creation_guard SELECT 'foreign keys remain enabled', foreign_keys = 1 FROM pragma_foreign_keys;
INSERT INTO _phase1_creation_guard SELECT 'no outgoing FK violations', NOT EXISTS (SELECT 1 FROM pragma_foreign_key_check);
